import { useState } from "react";

function ScoreForm({
	ranking,
	onRankingRender,
	onUpdateRanking,
	homeTeam,
	awayTeam,
	team1,
	team2,
	onSelectTeam1,
	onSelectTeam2,
	team1Score,
	team2Score,
	onAddP1Score,
	onAddP2Score,
	onAddScore,
	onAddTeam,
}) {
	// States
	const [createdTeam, setCreatedTeam] = useState("");

	const [point, setPoints] = useState(0);
	const [win, setWin] = useState(0);
	const [draw, setDraw] = useState(0);
	const [loss, setLoss] = useState(0);
	const [goalsFor, setGoalsFor] = useState(0);
	const [goalsAgainst, setGoalsAgainst] = useState(0);
	let goalsDifference = 0;

	// Handle submit form
	function handleSubmit(e) {
		e.preventDefault();

		if (ranking.length === 0) {
			const newTeam = {
				id: Date.now(),
				teamName: createdTeam,
				points: 0,
				wins: 0,
				draws: 0,
				losses: 0,
				goalsFor: 0,
				goalsAgainst: 0,
				goalDifference: 0,
			};
			onAddTeam(newTeam);
		} else {
			// Build the new result, and add it into the scoreBoard state/table.
			const newResult = {
				id: Date.now(),
				homeTeam: team1,
				awayTeam: team2,
				result: team1Score + " : " + team2Score,
			};
			if (team1 && team2) {
				onAddScore(newResult);
			} else {
				alert("Select both teams, please.");
			}
			if (newResult) {
				if (team1Score > team2Score) {
					const team1NewStats = ranking.map((team) => {
						if (team1 === team.teamName) {
							goalsDifference = team1Score - team2Score;
							return {
								...team,
								points: team.points + 3,
								wins: team.wins + 1,
								draws: team.draws,
								losses: team.losses,
								goalsFor: team.goalsFor + team1Score,
								goalsAgainst: team.goalsAgainst + team2Score,
								goalDifference: team.goalDifference + goalsDifference,
							};
						} else if (team2 === team.teamName) {
							goalsDifference = team2Score - team1Score;
							return {
								...team,
								points: team.points,
								wins: team.wins,
								draws: team.draws,
								losses: team.losses + 1,
								goalsFor: team.goalsFor + team2Score,
								goalsAgainst: team.goalsAgainst + team1Score,
								goalDifference: team.goalDifference + goalsDifference,
							};
						} else {
							return team;
						}
					});
					onUpdateRanking(team1NewStats);
				} else if (team2Score > team1Score) {
					const team1NewStats = ranking.map((team) => {
						if (team2 === team.teamName) {
							goalsDifference = team2Score - team1Score;
							return {
								...team,
								points: team.points + 3,
								wins: team.wins + 1,
								draws: team.draws,
								losses: team.losses,
								goalsFor: team.goalsFor + team2Score,
								goalsAgainst: team.goalsAgainst + team1Score,
								goalDifference: team.goalDifference + goalsDifference,
							};
						} else if (team1 === team.teamName) {
							goalsDifference = team1Score - team2Score;
							return {
								...team,
								points: team.points,
								wins: team.wins,
								draws: team.draws,
								losses: team.losses + 1,
								goalsFor: team.goalsFor + team1Score,
								goalsAgainst: team.goalsAgainst + team2Score,
								goalDifference: team.goalDifference + goalsDifference,
							};
						} else {
							return team;
						}
					});
					onUpdateRanking(team1NewStats);
				} else {
					const team1NewStats = ranking.map((team) => {
						if (team1 === team.teamName) {
							goalsDifference = team1Score - team2Score;
							return {
								...team,
								points: team.points + 1,
								wins: team.wins,
								draws: team.draws + 1,
								losses: team.losses,
								goalsFor: team.goalsFor + team1Score,
								goalsAgainst: team.goalsAgainst + team2Score,
								goalDifference: team.goalDifference + goalsDifference,
							};
						} else if (team2 === team.teamName) {
							goalsDifference = team2Score - team1Score;
							return {
								...team,
								points: team.points + 1,
								wins: team.wins,
								draws: team.draws + 1,
								losses: team.losses,
								goalsFor: team.goalsFor + team2Score,
								goalsAgainst: team.goalsAgainst + team1Score,
								goalDifference: team.goalDifference + goalsDifference,
							};
						} else {
							return team;
						}
					});
					onUpdateRanking(team1NewStats);
				}
			} else {
				console.log("Nothing to update!");
			}
			// Re-render Ranking
			onRankingRender();
		}
	}

	const playerObj = ranking.map((player) => player);
	const { teamName } = playerObj;

	return (
		<div className="scores">
			{ranking.length > 0 && (
				<form onSubmit={handleSubmit}>
					<span>
						<select
							defaultValue={"home"}
							value={teamName}
							onChange={(e) => onSelectTeam1(e.target.value)}
							required
						>
							<option value="home" disabled>
								Home Team
							</option>

							<option value={playerObj[0].teamName}>
								{playerObj[0].teamName}
							</option>
							<option value={playerObj[1].teamName}>
								{playerObj[1].teamName}
							</option>
							<option value={playerObj[2].teamName}>
								{playerObj[2].teamName}
							</option>
						</select>
						<input
							type="number"
							value={team1Score}
							onChange={(e) => onAddP1Score(Number(e.target.value))}
							required
						/>
					</span>
					:
					<span>
						<select
							defaultValue={"away"}
							value={teamName}
							onChange={(e) => onSelectTeam2(e.target.value)}
							required
						>
							<option value="away" disabled>
								Away Team
							</option>
							<option value={playerObj[0].teamName}>
								{playerObj[0].teamName}
							</option>
							<option value={playerObj[1].teamName}>
								{playerObj[1].teamName}
							</option>
							<option value={playerObj[2].teamName}>
								{playerObj[2].teamName}
							</option>
						</select>
						<input
							type="number"
							value={team2Score}
							onChange={(e) => onAddP2Score(Number(e.target.value))}
							required
						/>
					</span>
					<button>Add</button>
				</form>
			)}
			{ranking.length === 0 && (
				<input
					className="input-team"
					type="text"
					placeholder="Team name..."
					value={createdTeam}
					onChange={(e) => e.target.value}
				/>
			)}
		</div>
	);
}
export default ScoreForm;
